  3	// TestOQ3FailureNumber runs the frozen ledger and publishes the failure number with its components
  4	// and a separate validity verdict. Environment:
  5	//   OQ3_EVIDENCE_DIR  where the ledger, per-scenario results, captures and summary are written (required)
  6	//   OQ3_GOLDENS       the frozen pre-G1 goldens directory (required)
  7	//   OQ3_FREEZE=1      write a golden when absent (only for the pre-G1 baseline run that creates them)
  8	//   OQ3_MODE          baseline (valid run required; the number is recorded) or accept (the number must be 0)
  9	//   OQ3_SCENARIOS     comma-separated scenario ids, or "all"; empty is refused
 10	//   OQ3_SOURCE        a description of the candidate under test, recorded in goldens and the summary
 11	
 12	package cmd
 13	
 14	import (
 15		"bytes"
 16		"errors"
 17		"fmt"
 18		"net/http"
 19		"os"
 20		"path/filepath"
 21		"strings"
 22		"testing"
 23		"time"
 24	)
