 76	func TestOQ3FailureNumber(t *testing.T) {
 77		evidence := os.Getenv("OQ3_EVIDENCE_DIR")
 78		goldens := os.Getenv("OQ3_GOLDENS")
 79		mode := os.Getenv("OQ3_MODE")
 80		if evidence == "" || goldens == "" || (mode != "baseline" && mode != "accept") {
 81			t.Fatalf("OQ3_EVIDENCE_DIR, OQ3_GOLDENS and OQ3_MODE (baseline|accept) are required")
 82		}
 83		freeze := os.Getenv("OQ3_FREEZE") == "1"
 84		if freeze && mode != "baseline" {
 85			t.Fatalf("goldens may only be frozen by a baseline run")
 86		}
 87		source := os.Getenv("OQ3_SOURCE")
 88		all := oq3AllScenarios()
 89		selected, err := oq3Select(all, os.Getenv("OQ3_SCENARIOS"))
 90		if err != nil {
 91			t.Fatal(err)
 92		}
 93		ledgerSHA, ledgerJSON := oq3LedgerSHA(all)
 94		if err := os.MkdirAll(evidence, 0o755); err != nil {
 95			t.Fatal(err)
 96		}
 97		if err := os.WriteFile(filepath.Join(evidence, "ledger.json"), ledgerJSON, 0o644); err != nil {
 98			t.Fatal(err)
 99		}
100		t.Logf("OQ3 ledger sha256 %s (%d scenarios), selected %d", ledgerSHA, len(all), len(selected))
101	
102		var results []oq3ScenarioResult
103		var refResults []oq3ScenarioResult
104		for _, sc := range selected {
105			start := time.Now()
106			d := oq3StartDaemon(t)
107			s := oq3NewSandbox(t, sc.ID)
108			run := oq3NewRun(t, sc, d, s)
109			if strings.HasPrefix(sc.ID, "E") {
110				if bin := os.Getenv("OQ3_BINARY"); bin != "" {
111					run.builtBinary = []string{bin}
112				}
113			}
114			run.execute()
115			res := run.score(goldens, freeze, source)
116			results = append(results, res)
117			if err := oq3WriteJSON(filepath.Join(evidence, "scenarios", sc.ID+".json"), res); err != nil {
118				t.Fatal(err)
119			}
120			// Reference arm (Q7 b): the expected requests, sent through real HTTP to a fresh fake daemon
121			// under the same labels, must all score correct. Kept outside the candidate's numbers.
122			ref := oq3ReferenceArm(t, run, res, goldens)
123			refResults = append(refResults, ref)
124			if err := oq3WriteJSON(filepath.Join(evidence, "reference", sc.ID+".json"), ref); err != nil {
125				t.Fatal(err)
126			}
127			t.Logf("OQ3 scenario %s done in %s: %d deliveries recorded, %d invalid", sc.ID, time.Since(start).Round(time.Millisecond), len(res.Deliveries), len(res.Invalid))
128		}
129	
130		sum := oq3Summarise(results, mode, source, ledgerSHA)
131		if problems := oq3Completeness(selected, results); len(problems) > 0 {
132			sum.Valid = false
133			sum.Invalid = append(sum.Invalid, problems...)
134		}
135		refSum := oq3Summarise(refResults, "reference", "expected requests sent by the reference arm", ledgerSHA)
136		if refSum.FailureNumerator != 0 || refSum.ObservedDeliveries == 0 {
137			sum.Valid = false
138			sum.Invalid = append(sum.Invalid, fmt.Sprintf("reference arm did not read correct deliveries as correct: %d bad or missing of %d", refSum.FailureNumerator, refSum.ObservedDeliveries))
139		}
140		if err := oq3WriteJSON(filepath.Join(evidence, "summary.json"), sum); err != nil {
141			t.Fatal(err)
142		}
143		if err := oq3WriteJSON(filepath.Join(evidence, "reference-summary.json"), refSum); err != nil {
144			t.Fatal(err)
145		}
146		t.Logf("OQ3_FAILURE_NUMBER=%s valid=%v observed=%d bad=%d missing=%d trials=%d", sum.FailureNumber, sum.Valid, sum.ObservedDeliveries, sum.BadObserved, sum.MissingRequired, sum.Trials)
147		t.Logf("OQ3_REFERENCE_ARM=%s observed=%d", refSum.FailureNumber, refSum.ObservedDeliveries)
148		if !sum.Valid {
149			t.Fatalf("OQ3 run is not valid: %s", strings.Join(sum.Invalid, " | "))
150		}
151		if mode == "accept" {
152			if sum.FailureNumerator != 0 {
153				t.Fatalf("OQ3 acceptance: failure number %s", sum.FailureNumber)
154			}
155			// Operations must pass on their own evidence; "done" is accepted only for the existing
156			// terminal commands (/system, /tools, /new, /compact, /model), whose effect is checked by the
157			// deliveries that follow them. "unobserved" and "absent" fail.
158			for k, n := range sum.OperationVerdicts {
159				if !strings.HasSuffix(k, ":pass") && k != "terminal-slash:done" {
160					t.Fatalf("OQ3 acceptance: operation verdict %s x%d", k, n)
161				}
162			}
163			for k, n := range sum.RefusalVerdicts {
164				if !strings.HasSuffix(k, ":pass") {
165					t.Fatalf("OQ3 acceptance: required refusal %s x%d", k, n)
166				}
167			}
168		}
169	}
