171	// oq3ReferenceArm sends, for every delivery the candidate was scored on, the request a correct G1
172	// implementation would send (the oracle's expectation), through real HTTP to a fresh fake daemon,
173	// and scores the captures with the same scorer. A correct delivery must read as correct.
174	func oq3ReferenceArm(t *testing.T, run *oq3Run, res oq3ScenarioResult, goldens string) oq3ScenarioResult {
175		rd := oq3StartDaemon(t)
176		for _, dl := range res.Deliveries {
177			if dl.Expect == nil || dl.Golden == "" {
178				continue
179			}
180			golden, err := oq3LoadGolden(dl.Golden)
181			if err != nil {
182				continue
183			}
184			exp, err := oq3Transform(golden, *dl.Expect, func(model string) (string, bool) {
185				s, ok := rd.modelSystems[oq3ModelBase(model)]
186				return s, ok
187			})
188			if err != nil {
189				continue
190			}
191			body, err := oq3MarshalCanonical(exp)
192			if err != nil {
193				t.Fatal(err)
194			}
195			rd.setLabel(dl.Label)
196			resp, err := http.Post(rd.srv.URL+"/api/chat", "application/json", bytes.NewReader(body))
197			if err != nil {
198				t.Fatalf("reference arm post: %v", err)
199			}
200			resp.Body.Close()
201		}
202		refRun := oq3NewRun(t, run.sc, rd, run.s)
203		// The reference arm reuses the scenario's steps for attribution; its captures are the expected
204		// requests. Summariser requests are not re-sent, so compaction-demonstration checks do not apply.
205		scored := refRun.scoreDeliveriesOnly(goldens)
206		return scored
207	}

