  3	// OQ-3 oracle: what a correct delivery looks like, derived independently of the code under test.
  4	//
  5	// The expected request for every delivery is built from two inputs only: the request the unchanged
  6	// (pre-G1) candidate sent for the same step, frozen as a golden, and the composition rule of the G1
  7	// blueprint §5 (docs/_design/G1_PERSISTED_INSTRUCTIONS.md:200-206) implemented here from its text.
  8	// No production composition code is called. The admission field is §6.3 A1 (version 1).
  9	
 10	package cmd
 11	
 12	import (
 13		"bytes"
 14		"encoding/json"
 15		"fmt"
 16		"reflect"
 17		"regexp"
 18		"sort"
 19		"strings"
 20	)
 21	
 22	// oq3Texts are the contrasting instruction profiles. Each carries sentinels at its start, middle and
 23	// end, a line break and a non-ASCII character, so truncation, re-encoding or partial loss is visible.
 24	var oq3Texts = map[string]string{
 25		"A": "SENTINEL-A-START-5d2c OQ3 instruction profile A: answer in Australian English and keep replies short.\n" +
 26			"SENTINEL-A-MID-9e41 Name the café you would recommend — this line checks bytes beyond ASCII.\n" +
 27			"Close every reply with the word ALPHA. SENTINEL-A-END-b7f0",
 28		"B": "SENTINEL-B-START-2a6e OQ3 instruction profile B: answer as a checklist of numbered steps.\n" +
 29			"SENTINEL-B-MID-4c18 Prefer metric units — naïve estimates are acceptable here.\n" +
 30			"Close every reply with the word BRAVO. SENTINEL-B-END-83d9",
 31	}
 32	
 33	// oq3AllSentinels lists every profile sentinel; none may appear anywhere a carrier is not expected.
 34	var oq3AllSentinels = []string{"SENTINEL-A-START-5d2c", "SENTINEL-A-MID-9e41", "SENTINEL-A-END-b7f0",
 35		"SENTINEL-B-START-2a6e", "SENTINEL-B-MID-4c18", "SENTINEL-B-END-83d9"}
 36	
 37	const oq3HeaderPrefix = "User-configured instructions; revision "
 38	
 39	func oq3Header(rev, gen int) string {
 40		return fmt.Sprintf("User-configured instructions; revision %d; selection %d:\n", rev, gen)
 41	}
 42	
 43	var oq3HeaderRE = regexp.MustCompile(`User-configured instructions; revision ([0-9]+); selection ([0-9]+):\n`)
 44	
 45	// oq3Expect is one required delivery's expectation.
 46	type oq3Expect struct {
 47		Carrier bool   `json:"carrier"`
 48		Rev     int    `json:"revision,omitempty"`
 49		Gen     int    `json:"generation,omitempty"`
 50		Text    string `json:"text,omitempty"` // key into oq3Texts
 51		// Adapter decides where the base comes from: "desktop" (model-system text of the request's model,
 52		// §5) or "terminal" (the system message the pre-G1 candidate sent, which is the built-in base).
 53		Adapter string `json:"adapter"`
 54	}
 55	
 56	// ---------------------------------------------------------------------------------------------
 57	// Normalisation: only declared variable inputs are parameterised (Method 04 T-07).
 58	
 59	var (
 60		oq3DateRE = regexp.MustCompile(`Current date: [A-Z][a-z]+, [A-Z][a-z]+ [0-9]{1,2}, [0-9]{4}\.`)
 61	)
 62	
 63	// oq3Normalise decodes a request body and replaces declared variable text: the terminal prompt's
 64	// date line and the sandbox root path. Numbers stay exact (json.Number).
 65	func oq3Normalise(body []byte, sandboxRoot string) (any, error) {
 66		dec := json.NewDecoder(bytes.NewReader(body))
 67		dec.UseNumber()
 68		var v any
 69		if err := dec.Decode(&v); err != nil {
 70			return nil, err
 71		}
 72		if dec.More() {
 73			return nil, fmt.Errorf("more than one JSON value")
 74		}
 75		return oq3Walk(v, func(s string) string {
 76			s = oq3DateRE.ReplaceAllString(s, "Current date: <DATE>.")
 77			if sandboxRoot != "" {
 78				s = strings.ReplaceAll(s, sandboxRoot, "<SANDBOX>")
 79			}
 80			return s
 81		}), nil
 82	}
 83	
 84	func oq3Walk(v any, f func(string) string) any {
 85		switch x := v.(type) {
 86		case map[string]any:
 87			out := make(map[string]any, len(x))
 88			for k, val := range x {
 89				out[k] = oq3Walk(val, f)
 90			}
 91			return out
 92		case []any:
 93			out := make([]any, len(x))
 94			for i, val := range x {
 95				out[i] = oq3Walk(val, f)
 96			}
 97			return out
 98		case string:
 99			return f(x)
100		default:
101			return v
102		}
103	}
104	
105	func oq3DeepCopy(v any) any {
106		return oq3Walk(v, func(s string) string { return s })
107	}
108	
109	func oq3Messages(req any) []map[string]any {
110		m, _ := req.(map[string]any)
111		raw, _ := m["messages"].([]any)
112		out := make([]map[string]any, 0, len(raw))
113		for _, r := range raw {
114			if mm, ok := r.(map[string]any); ok {
115				out = append(out, mm)
116			}
117		}
118		return out
119	}
120	
121	func oq3Str(m map[string]any, k string) string {
122		s, _ := m[k].(string)
123		return s
124	}
125	
126	// ---------------------------------------------------------------------------------------------
127	// The expected request.
128	
129	// oq3Transform returns the request a correct G1 implementation sends for this delivery, given the
130	// normalised pre-G1 golden for the same step and the expectation. modelSystem is the model-system
131	// text the fake daemon serves for the request's model (desktop base, §5).
132	func oq3Transform(golden any, e oq3Expect, modelSystem func(model string) (string, bool)) (any, error) {
133		exp := oq3DeepCopy(golden)
134		m, ok := exp.(map[string]any)
135		if !ok {
136			return nil, fmt.Errorf("golden is not an object")
137		}
138		if !e.Carrier {
139			delete(m, "admission")
140			return m, nil
141		}
142		text, ok := oq3Texts[e.Text]
143		if !ok {
144			return nil, fmt.Errorf("unknown text %q", e.Text)
145		}
146		carrier := oq3Header(e.Rev, e.Gen) + text
147		msgs, _ := m["messages"].([]any)
148		switch e.Adapter {
149		case "desktop":
150			if len(msgs) > 0 {
151				if first, ok := msgs[0].(map[string]any); ok && oq3Str(first, "role") == "system" {
152					// A pre-G1 desktop request only leads with a system message when MCP servers supplied
153					// instructions; the blueprint does not state how model-system and MCP text are joined
154					// (G1_PERSISTED_INSTRUCTIONS.md:204), so this oracle refuses to guess.
155					return nil, fmt.Errorf("oracle unresolved: desktop golden already leads with a system message (MCP join unspecified)")
156				}
157			}
158			model, _ := m["model"].(string)
159			base, ok := modelSystem(model)
160			if !ok {
161				return nil, fmt.Errorf("no model-system text for %q", model)
162			}
163			content := carrier
164			if base != "" {
165				content = base + "\n\n" + carrier
166			}
167			m["messages"] = append([]any{map[string]any{"role": "system", "content": content}}, msgs...)
168		case "terminal":
169			if len(msgs) > 0 {
170				if first, ok := msgs[0].(map[string]any); ok && oq3Str(first, "role") == "system" {
171					base := oq3Str(first, "content")
172					nf := oq3DeepCopy(first).(map[string]any)
173					if base != "" {
174						nf["content"] = base + "\n\n" + carrier
175					} else {
176						nf["content"] = carrier
177					}
178					msgs[0] = nf
179					m["messages"] = msgs
180					break
181				}
182			}
183			// No built-in base (for example after /system off): the carrier alone leads (§5).
184			m["messages"] = append([]any{map[string]any{"role": "system", "content": carrier}}, msgs...)
185		default:
186			return nil, fmt.Errorf("unknown adapter %q", e.Adapter)
187		}
188		m["admission"] = map[string]any{"version": json.Number("1")}
189		return m, nil
190	}
191	
192	// ---------------------------------------------------------------------------------------------
193	// Scoring one observed delivery.
194	
195	type oq3DeliveryVerdict struct {
196		Correct    bool     `json:"correct"`
197		Categories []string `json:"categories,omitempty"`
198		Detail     string   `json:"detail,omitempty"`
199	}
200	
201	// oq3Score compares one observed request (normalised) with the expected request, and when they
202	// differ, names every category of difference it can identify. An observed request that differs is
203	// one bad delivery, however many categories it has.
204	func oq3Score(observed, expected any, e oq3Expect) oq3DeliveryVerdict {
205		if reflect.DeepEqual(observed, expected) {
206			return oq3DeliveryVerdict{Correct: true}
207		}
208		cats := map[string]bool{}
209		var notes []string
210		obsMsgs := oq3Messages(observed)
211		expMsgs := oq3Messages(expected)
212	
213		// Where do carrier headers occur in the observed request?
214		type hit struct {
215			msg, rev, gen int
216			role          string
217		}
218		var hits []hit
219		for i, msg := range obsMsgs {
220			for _, mm := range oq3HeaderRE.FindAllStringSubmatch(oq3Str(msg, "content"), -1) {
221				var r, g int
222				fmt.Sscan(mm[1], &r)
223				fmt.Sscan(mm[2], &g)
224				hits = append(hits, hit{msg: i, rev: r, gen: g, role: oq3Str(msg, "role")})
225			}
226		}
227		obsJSON, _ := json.Marshal(observed)
228		om, _ := observed.(map[string]any)
229		_, hasAdmission := om["admission"]
230	
231		if e.Carrier {
232			text := oq3Texts[e.Text]
233			switch {
234			case len(hits) == 0:
235				cats["missing"] = true
236			case len(hits) > 1:
237				cats["duplicated"] = true
238			default:
239				h := hits[0]
240				if h.rev != e.Rev || h.gen != e.Gen {
241					cats["wrong-revision"] = true
242					notes = append(notes, fmt.Sprintf("header revision %d selection %d, expected %d/%d", h.rev, h.gen, e.Rev, e.Gen))
243				}
244				if h.msg != 0 || h.role != "system" {
245					cats["misplaced"] = true
246				}
247				content := oq3Str(obsMsgs[h.msg], "content")
248				idx := strings.Index(content, oq3HeaderPrefix)
249				if idx < 0 {
250					cats["other"] = true
251					break
252				}
253				after := content[idx:]
254				if loc := oq3HeaderRE.FindStringIndex(after); loc != nil {
255					after = after[loc[1]:]
256				}
257				if after != text {
258					cats["altered"] = true
259				}
260				if len(expMsgs) > 0 {
261					expContent := oq3Str(expMsgs[0], "content")
262					if ei := strings.Index(expContent, oq3HeaderPrefix); ei >= 0 && content[:idx] != expContent[:ei] {
263						cats["base-lost"] = true
264					}
265				}
266			}
267			if !hasAdmission {
268				cats["admission-missing"] = true
269			}
270		} else {
271			if len(hits) > 0 {
272				cats["unexpected-carrier"] = true
273			}
274			if hasAdmission {
275				cats["unexpected-admission"] = true
276			}
277		}
278		// Profile text anywhere the expectation does not put it.
279		expJSON, _ := json.Marshal(expected)
280		for _, s := range oq3AllSentinels {
281			if strings.Count(string(obsJSON), s) > strings.Count(string(expJSON), s) {
282				cats["leaked"] = true
283				notes = append(notes, "sentinel "+s)
284			}
285		}
286		// Everything outside the leading message must equal the expectation (history, tools, options).
287		obsRest, expRest := oq3WithoutLeadingSystem(observed), oq3WithoutLeadingSystem(expected)
288		if !reflect.DeepEqual(obsRest, expRest) {
289			cats["request-changed"] = true
290			notes = append(notes, oq3FirstDifference(obsRest, expRest))
291		}
292		if len(cats) == 0 {
293			// Differs, but in a way none of the named checks isolates (for example the leading
294			// message's role or an extra field on it).
295			cats["other"] = true
296		}
297		out := make([]string, 0, len(cats))
298		for c := range cats {
299			out = append(out, c)
300		}
301		sort.Strings(out)
302		return oq3DeliveryVerdict{Correct: false, Categories: out, Detail: strings.Join(notes, "; ")}
303	}
304	
305	func oq3WithoutLeadingSystem(req any) any {
306		c := oq3DeepCopy(req)
307		m, ok := c.(map[string]any)
308		if !ok {
309			return c
310		}
311		delete(m, "admission")
312		msgs, _ := m["messages"].([]any)
313		if len(msgs) > 0 {
314			if first, ok := msgs[0].(map[string]any); ok && oq3Str(first, "role") == "system" {
315				msgs = msgs[1:]
316			}
317		}
318		m["messages"] = msgs
319		return m
320	}
321	
322	// oq3FirstDifference names the first top-level field (or message index) that differs.
323	func oq3FirstDifference(a, b any) string {
324		am, _ := a.(map[string]any)
325		bm, _ := b.(map[string]any)
326		keys := map[string]bool{}
327		for k := range am {
328			keys[k] = true
329		}
330		for k := range bm {
331			keys[k] = true
332		}
333		var ks []string
334		for k := range keys {
335			ks = append(ks, k)
336		}
337		sort.Strings(ks)
338		for _, k := range ks {
339			if !reflect.DeepEqual(am[k], bm[k]) {
340				if k == "messages" {
341					amsg, _ := am[k].([]any)
342					bmsg, _ := bm[k].([]any)
343					if len(amsg) != len(bmsg) {
344						return fmt.Sprintf("messages: %d observed, %d expected", len(amsg), len(bmsg))
345					}
346					for i := range amsg {
347						if !reflect.DeepEqual(amsg[i], bmsg[i]) {
348							return fmt.Sprintf("messages[%d] differs", i)
349						}
350					}
351				}
352				return "field " + k + " differs"
353			}
354		}
355		return "no top-level difference found"
356	}
357	
358	// oq3CheckSummariser is the separate expectation for a compaction summariser request (Q2): it keeps
359	// the compactor's own system prompt, and carries no carrier header and no profile text, so the
360	// carrier was neither injected into it nor stored in the history it summarises.
361	func oq3CheckSummariser(observed any) oq3DeliveryVerdict {
362		msgs := oq3Messages(observed)
363		var cats []string
364		if len(msgs) == 0 || oq3Str(msgs[0], "role") != "system" || !strings.HasPrefix(oq3Str(msgs[0], "content"), oq3CompactionSystemPrefix) {
365			cats = append(cats, "summariser-prompt-replaced")
366		}
367		b, _ := json.Marshal(observed)
368		if oq3HeaderRE.Match(b) || bytes.Contains(b, []byte("User-configured instructions")) {
369			cats = append(cats, "summariser-carries-header")
370		}
371		for _, s := range oq3AllSentinels {
372			if bytes.Contains(b, []byte(s)) {
373				cats = append(cats, "summariser-carries-profile")
374				break
375			}
376		}
377		return oq3DeliveryVerdict{Correct: len(cats) == 0, Categories: cats}
378	}

287	func (r *oq3Run) desktopTurn(i int, st oq3Step, label string) {
288		id := r.convIDs[st.Conv]
289		if id == "" {
290			id = "new"
291		}
292		body := map[string]any{"model": oq3Model, "prompt": st.Prompt}
293		if m := st.Args["model"]; m != "" {
294			body["model"] = m
295		}
296		if st.Args["think"] == "true" {
297			body["think"] = true
298		}
299		if st.Args["web_search"] == "true" {
300			body["web_search"] = true
301		}
302		if name := st.Args["attachment"]; name != "" {
303			body["attachments"] = []any{map[string]any{"filename": name, "data": base64.StdEncoding.EncodeToString([]byte("OQ3 attachment line one.\nOQ3 attachment line two.\n"))}}
304		}
305		if s := st.Args["fail"]; s != "" {
306			n, _ := strconv.Atoi(s)
307			r.d.failNext(label, n)
308		}
309		if st.Args["hold"] == "1" {
310			r.d.hold(label)
311			r.marksLabel[st.Conv] = label
312			ch := make(chan asyncResult, 1)
313			r.async[st.Conv] = ch
314			desk := r.desk
315			go func() {
316				newID, res := desk.chatBody(id, body)
317				ch <- asyncResult{id: newID, res: res}
318			}()
319			if !oq3WaitFor(30*time.Second, func() bool { return r.d.countLabel("POST", "/api/chat", label) >= 1 }) {
320				r.harnessFail("held desktop turn never reached the daemon")
321			}
322			r.event(i, st, "dispatched-held", map[string]any{"conversation": st.Conv})
323			return
324		}
325		newID, res := r.desk.chatBody(id, body)
326		if newID != "" && newID != "new" {
327			r.convIDs[st.Conv] = newID
328		}
329		r.event(i, st, "done", map[string]any{"status": res.Status, "chat_id": newID, "stream_tail": tail(res.Body, 400)})
330	}
