332	// ---------------------------------------------------------------------------------------------
333	// Terminal turns and commands.
334	
335	func (r *oq3Run) terminalTurn(i int, st oq3Step, label string) {
336		rounds, _ := strconv.Atoi(st.Args["tool_rounds"])
337		if rounds > 0 {
338			r.d.setToolRounds(label, rounds)
339		}
340		if st.Args["auto_compact"] == "1" {
341			r.d.reportPromptEval(label, 30000)
342		}
343		mark := r.term.rawLen()
344		if st.Args["hold"] == "1" {
345			r.d.hold(label)
346			r.marksLabel["terminal"] = label
347			r.marks["terminal"] = mark
348		}
349		r.term.typeLine(st.Prompt)
350		if !oq3WaitFor(30*time.Second, func() bool { return r.d.countLabel("POST", "/api/chat", label) >= 1 }) {
351			// No request reached the daemon: recorded, and scored as missing required deliveries.
352			r.event(i, st, "no-request", map[string]any{"screen_tail": tail(r.term.screen(), 1200)})
353			r.term.quiet(500*time.Millisecond, 10*time.Second)
354			return
355		}
356		if st.Args["hold"] == "1" {
357			r.event(i, st, "dispatched-held", nil)
358			return
359		}
360		for k := 0; k < rounds; k++ {
361			approvalMark := mark
362			if !oq3WaitFor(30*time.Second, func() bool { return r.term.screenContainsAfter(approvalMark, "Approve once") }) {
363				r.harnessFail("tool round %d: approval prompt never appeared; screen tail %q", k+1, tail(r.term.screen(), 1500))
364			}
365			want := r.d.countLabel("POST", "/api/chat", label) + 1
366			mark = r.term.rawLen()
367			r.term.key("1")
368			if !oq3WaitFor(30*time.Second, func() bool { return r.d.countLabel("POST", "/api/chat", label) >= want }) {
369				r.harnessFail("tool round %d: continuation never reached the daemon", k+1)
370			}
371		}
372		if !oq3WaitFor(30*time.Second, func() bool { return r.term.screenContainsAfter(mark, "OQ3-REPLY-") }) {
373			r.harnessFail("terminal never rendered the reply; screen tail %q", tail(r.term.screen(), 1500))
374		}
375		if st.Summarisers > 0 {
376			if !oq3WaitFor(30*time.Second, func() bool { return r.d.countSummaries(label) >= st.Summarisers }) {
377				r.event(i, st, "fail", map[string]any{"summarisers_seen": r.d.countSummaries(label), "screen_tail": tail(r.term.screen(), 1200)})
378				r.term.quiet(500*time.Millisecond, 10*time.Second)
379				return
380			}
381		}
382		r.term.quiet(500*time.Millisecond, 10*time.Second)
383		r.event(i, st, "done", nil)
384	}
385	
386	func (r *oq3Run) terminalSlash(i int, st oq3Step, label string) {
387		cmd := st.Args["cmd"]
388		mark := r.term.rawLen()
389		if pick := st.Args["pick"]; pick != "" {
390			r.term.typeLine(cmd)
391			if !oq3WaitFor(15*time.Second, func() bool { return r.term.screenContainsAfter(mark, pick) }) {
392				r.harnessFail("model picker never listed %s; screen tail %q", pick, tail(r.term.screen(), 1500))
393			}
394			r.term.quiet(400*time.Millisecond, 10*time.Second)
395			r.term.key(pick)
396			r.term.quiet(400*time.Millisecond, 10*time.Second)
397			r.term.key("\r")
398			r.term.quiet(700*time.Millisecond, 15*time.Second)
399			r.event(i, st, "done", map[string]any{"picked": pick, "screen_tail": tail(r.term.screen(), 600)})
400			return
401		}
402		r.term.typeLine(cmd)
403		if st.Summarisers > 0 {
404			if !oq3WaitFor(30*time.Second, func() bool { return r.d.countSummaries(label) >= st.Summarisers }) {
405				r.event(i, st, "fail", map[string]any{"summarisers_seen": r.d.countSummaries(label), "screen_tail": tail(r.term.screen(), 1200)})
406				r.term.quiet(500*time.Millisecond, 10*time.Second)
407				return
408			}
409		}
410		r.term.quiet(600*time.Millisecond, 15*time.Second)
411		unknown := r.term.screenContainsAfter(mark, "Unknown command")
412		verdict := "done"
413		switch {
414		case unknown:
415			verdict = "absent"
416		case st.Class == "required-refusal" || strings.HasPrefix(cmd, "/instructions"):
417			// The blueprint (§7) names no terminal output for /instructions reload or off, for success or
418			// for a refusal while a turn runs, so no positive evidence can be read from the screen. The
419			// absence of an error is not success: while a turn runs the screen only animates. Recorded
420			// as unobserved; acceptance treats it as a failure until the output is specified.
421			verdict = "unobserved"
422		}
423		r.event(i, st, verdict, map[string]any{"screen_tail": tail(oq3ANSI.ReplaceAllString(r.term.rawSince(mark), ""), 600)})
424	}
