426	// ---------------------------------------------------------------------------------------------
427	// Operation verdicts. "absent" means the designated surface does not exist at this commit (the
428	// application's HTML fallback or an unknown command); it is a failed operation, not a harness fault.
429	
430	func oq3IsHTML(res oq3HTTPResult) bool {
431		return strings.Contains(strings.ToLower(res.ContentType), "text/html") || strings.HasPrefix(strings.TrimSpace(strings.ToLower(res.Body)), "<!doctype html")
432	}
433	
434	func oq3ProfileVerdict(res oq3HTTPResult, want map[string]string) string {
435		if oq3IsHTML(res) || res.Status == http.StatusNotFound {
436			return "absent"
437		}
438		var p struct {
439			Revision string `json:"revision"`
440			Enabled  bool   `json:"enabled"`
441			Text     string `json:"text"`
442		}
443		if res.Status != 200 || json.Unmarshal([]byte(res.Body), &p) != nil {
444			return "fail"
445		}
446		if p.Revision != want["revision"] || fmt.Sprint(p.Enabled) != want["enabled"] || p.Text != oq3TextOrEmpty(want["text"]) {
447			return "fail"
448		}
449		return "pass"
450	}
451	
452	func oq3ReloadVerdict(res oq3HTTPResult, want map[string]string) string {
453		if oq3IsHTML(res) || res.Status == http.StatusNotFound {
454			return "absent"
455		}
456		if fmt.Sprint(res.Status) != want["status"] {
457			return "fail"
458		}
459		if want["code"] != "" {
460			var e struct {
461				Error struct {
462					Code string `json:"code"`
463				} `json:"error"`
464			}
465			if json.Unmarshal([]byte(res.Body), &e) != nil || e.Error.Code != want["code"] {
466				return "fail"
467			}
468			return "pass"
469		}
470		var sel struct {
471			Revision   string `json:"revision"`
472			Generation string `json:"generation"`
473		}
474		if json.Unmarshal([]byte(res.Body), &sel) != nil || sel.Revision != want["revision"] || sel.Generation != want["generation"] {
475			return "fail"
476		}
477		return "pass"
478	}
