480	// storeIdentity reads the designated instruction store (blueprint §3, §3.1) for distinct terminal
481	// conversation identities. Before G1 the store does not exist, which is reported as absent.
482	func (r *oq3Run) storeIdentity(want map[string]string) string {
483		path := filepath.Join(r.s.home, ".ollama", "instructions", "instructions.sqlite")
484		if _, err := os.Stat(path); err != nil {
485			return "absent"
486		}
487		db, err := sql.Open("sqlite3", "file:"+path+"?mode=ro")
488		if err != nil {
489			return "fail"
490		}
491		defer db.Close()
492		var n int
493		if err := db.QueryRow(`SELECT COUNT(DISTINCT conversation_id) FROM conversations WHERE namespace = 'terminal'`).Scan(&n); err != nil {
494			return "fail"
495		}
496		min, _ := strconv.Atoi(want["min_terminal"])
497		if n >= min {
498			return "pass"
499		}
500		return "fail"
501	}
