503	// ---------------------------------------------------------------------------------------------
504	// Scoring.
505	
506	type oq3Delivery struct {
507		Scenario string             `json:"scenario"`
508		Step     int                `json:"step"`
509		Label    string             `json:"label"`
510		Trial    string             `json:"trial"`
511		Index    int                `json:"index"`
512		Expect   *oq3Expect         `json:"expect,omitempty"`
513		Seq      int                `json:"capture_seq,omitempty"`
514		Status   string             `json:"status"` // correct | bad | missing | unexpected
515		Verdict  oq3DeliveryVerdict `json:"verdict"`
516		Golden   string             `json:"golden,omitempty"`
517	}
518	
519	type oq3ScenarioResult struct {
520		Scenario   oq3Scenario   `json:"scenario"`
521		Events     []oq3Event    `json:"events"`
522		Deliveries []oq3Delivery `json:"deliveries"`
523		Auxiliary  []oq3Delivery `json:"auxiliary"`
524		Captures   []oq3Capture  `json:"captures"`
525		Invalid    []string      `json:"invalid,omitempty"`
526		Sandbox    string        `json:"sandbox"`
527	}
528	
529	func oq3GoldenPath(dir, sc string, step, idx int) string {
530		return filepath.Join(dir, sc, fmt.Sprintf("%02d-%d.json", step, idx))
531	}
532	
533	type oq3GoldenFile struct {
534		Scenario string    `json:"scenario"`
535		Step     int       `json:"step"`
536		Index    int       `json:"index"`
537		Label    string    `json:"label"`
538		Trial    string    `json:"trial"`
539		Expect   oq3Expect `json:"expect"`
540		Request  any       `json:"request"`
541		Source   string    `json:"source"`
542	}
543	
544	// score attributes every captured /api/chat request to the step that caused it and scores it.
545	// freeze: when a golden is absent, the observed pre-G1 request becomes the golden (baseline only).
546	func (r *oq3Run) score(goldenDir string, freeze bool, source string) oq3ScenarioResult {
547		res := oq3ScenarioResult{Scenario: r.sc, Events: r.events, Invalid: append([]string(nil), r.invalid...), Sandbox: r.s.root}
548		caps := r.d.snapshot()
549		res.Captures = caps
550		byLabel := map[string][]oq3Capture{}
551		for _, c := range caps {
552			if c.Method == "POST" && c.Path == "/api/chat" {
553				byLabel[c.Label] = append(byLabel[c.Label], c)
554			}
555		}
556		known := map[string]bool{}
557		for i, st := range r.sc.Steps {
558			label := oq3Label(r.sc.ID, i, st.Op)
559			known[label] = true
560			var turns, sums []oq3Capture
561			for _, c := range byLabel[label] {
562				if c.Response == "summary" {
563					sums = append(sums, c)
564				} else {
565					turns = append(turns, c)
566				}
567			}
568			// Summariser requests: their own expectation (Q2).
569			for k, c := range sums {
570				obs, err := oq3Normalise(c.Body, r.s.root)
571				d := oq3Delivery{Scenario: r.sc.ID, Step: i, Label: label, Trial: st.Trial, Index: k, Seq: c.Seq}
572				if err != nil {
573					d.Status, d.Verdict = "bad", oq3DeliveryVerdict{Categories: []string{"malformed-capture"}, Detail: err.Error()}
574				} else {
575					d.Verdict = oq3CheckSummariser(obs)
576					d.Status = map[bool]string{true: "correct", false: "bad"}[d.Verdict.Correct]
577				}
578				res.Auxiliary = append(res.Auxiliary, d)
579			}
580			if st.Summarisers > 0 && len(sums) < st.Summarisers {
581				res.Invalid = append(res.Invalid, fmt.Sprintf("%s: compaction did not happen (%d summariser requests, %d required)", label, len(sums), st.Summarisers))
582			}
583			if st.Class != "required-dispatch" {
584				if len(turns) > 0 {
585					res.Invalid = append(res.Invalid, fmt.Sprintf("%s: %d unclassified model requests under a non-dispatch step", label, len(turns)))
586				}
587				continue
588			}
589			for k := 0; k < len(st.Expect) || k < len(turns); k++ {
590				d := oq3Delivery{Scenario: r.sc.ID, Step: i, Label: label, Trial: st.Trial, Index: k}
591				if k < len(st.Expect) {
592					e := st.Expect[k]
593					d.Expect = &e
594				}
595				if k >= len(turns) {
596					d.Status = "missing"
597					d.Verdict = oq3DeliveryVerdict{Categories: []string{"not-dispatched"}}
598					res.Deliveries = append(res.Deliveries, d)
599					continue
600				}
601				c := turns[k]
602				d.Seq = c.Seq
603				obs, err := oq3Normalise(c.Body, r.s.root)
604				if err != nil {
605					d.Status, d.Verdict = "bad", oq3DeliveryVerdict{Categories: []string{"malformed-capture"}, Detail: err.Error()}
606					res.Invalid = append(res.Invalid, fmt.Sprintf("%s: malformed capture %d", label, c.Seq))
607					res.Deliveries = append(res.Deliveries, d)

600				}
601				c := turns[k]
602				d.Seq = c.Seq
603				obs, err := oq3Normalise(c.Body, r.s.root)
604				if err != nil {
605					d.Status, d.Verdict = "bad", oq3DeliveryVerdict{Categories: []string{"malformed-capture"}, Detail: err.Error()}
606					res.Invalid = append(res.Invalid, fmt.Sprintf("%s: malformed capture %d", label, c.Seq))
607					res.Deliveries = append(res.Deliveries, d)
608					continue
609				}
610				if d.Expect == nil {
611					d.Status = "unexpected"
612					d.Verdict = oq3DeliveryVerdict{Categories: []string{"unexpected-request"}}
613					res.Invalid = append(res.Invalid, fmt.Sprintf("%s: more model requests than declared (%d > %d)", label, len(turns), len(st.Expect)))
614					res.Deliveries = append(res.Deliveries, d)
615					continue
616				}
617				gp := oq3GoldenPath(goldenDir, r.sc.ID, i, k)
618				d.Golden = gp
619				golden, gerr := oq3LoadGolden(gp)
620				if gerr != nil {
621					if !freeze {
622						d.Status = "bad"
623						d.Verdict = oq3DeliveryVerdict{Categories: []string{"no-golden"}, Detail: gerr.Error()}
624						res.Invalid = append(res.Invalid, fmt.Sprintf("%s: no golden %s", label, gp))
625						res.Deliveries = append(res.Deliveries, d)
626						continue
627					}
628					gf := oq3GoldenFile{Scenario: r.sc.ID, Step: i, Index: k, Label: label, Trial: st.Trial, Expect: *d.Expect, Request: obs, Source: source}
629					if err := oq3WriteJSON(gp, gf); err != nil {
630						r.t.Fatalf("write golden: %v", err)
631					}
632					golden = obs
633				}
634				exp, terr := oq3Transform(golden, *d.Expect, func(model string) (string, bool) {
635					s, ok := r.d.modelSystems[oq3ModelBase(model)]
636					return s, ok
637				})
638				if terr != nil {
639					d.Status = "bad"
640					d.Verdict = oq3DeliveryVerdict{Categories: []string{"oracle-unresolved"}, Detail: terr.Error()}
641					res.Invalid = append(res.Invalid, fmt.Sprintf("%s: %v", label, terr))
642					res.Deliveries = append(res.Deliveries, d)
643					continue
644				}
645				d.Verdict = oq3Score(obs, exp, *d.Expect)
646				d.Status = map[bool]string{true: "correct", false: "bad"}[d.Verdict.Correct]
647				res.Deliveries = append(res.Deliveries, d)
648			}
649		}
650		for label, cs := range byLabel {
651			if !known[label] {
652				res.Invalid = append(res.Invalid, fmt.Sprintf("%d model requests under unknown label %q", len(cs), label))
653			}
654		}
655		// Compaction must be demonstrable at the request boundary: the first request after a compaction
656		// step carries the summariser's text in its history.
657		for i, st := range r.sc.Steps {
658			if st.Summarisers == 0 || st.Op != "terminal-slash" {
659				continue
660			}
661			for j := i + 1; j < len(r.sc.Steps); j++ {
662				if r.sc.Steps[j].Class != "required-dispatch" {
663					continue
664				}
665				nl := oq3Label(r.sc.ID, j, r.sc.Steps[j].Op)
666				cs := byLabel[nl]
667				if len(cs) == 0 || !strings.Contains(string(cs[0].Body), "OQ3-SUMMARY") {
668					res.Invalid = append(res.Invalid, fmt.Sprintf("%s: the next request (%s) does not carry the compacted history", oq3Label(r.sc.ID, i, st.Op), nl))
669				}
670				break
671			}
672		}
673		return res
674	}
675	
676	// scoreDeliveriesOnly scores the requests captured under each dispatch step against that step's
677	// expectations and the frozen goldens, without freezing and without the omission, summariser and
678	// compaction checks. The reference arm uses it: it only re-sends requests that have a golden.
679	func (r *oq3Run) scoreDeliveriesOnly(goldenDir string) oq3ScenarioResult {
680		res := oq3ScenarioResult{Scenario: r.sc, Sandbox: r.s.root}
681		caps := r.d.snapshot()
682		res.Captures = caps
683		for i, st := range r.sc.Steps {
684			if st.Class != "required-dispatch" {
685				continue
686			}
687			label := oq3Label(r.sc.ID, i, st.Op)
688			k := 0
689			for _, c := range caps {
690				if c.Path != "/api/chat" || c.Label != label {
691					continue
692				}
693				d := oq3Delivery{Scenario: r.sc.ID, Step: i, Label: label, Trial: st.Trial, Index: k, Seq: c.Seq}
694				if k >= len(st.Expect) {
695					d.Status, d.Verdict = "unexpected", oq3DeliveryVerdict{Categories: []string{"unexpected-request"}}
696					res.Deliveries = append(res.Deliveries, d)
697					k++
698					continue
699				}
700				e := st.Expect[k]
701				d.Expect = &e
702				gp := oq3GoldenPath(goldenDir, r.sc.ID, i, k)
703				d.Golden = gp
704				k++
705				obs, err := oq3Normalise(c.Body, r.s.root)
706				if err != nil {
707					d.Status, d.Verdict = "bad", oq3DeliveryVerdict{Categories: []string{"malformed-capture"}}
708					res.Deliveries = append(res.Deliveries, d)
709					continue
710				}
711				golden, err := oq3LoadGolden(gp)
712				if err != nil {
713					d.Status, d.Verdict = "bad", oq3DeliveryVerdict{Categories: []string{"no-golden"}}
714					res.Deliveries = append(res.Deliveries, d)
715					continue
716				}
717				exp, err := oq3Transform(golden, e, func(model string) (string, bool) {
718					s, ok := r.d.modelSystems[oq3ModelBase(model)]
719					return s, ok
720				})
721				if err != nil {
722					d.Status, d.Verdict = "bad", oq3DeliveryVerdict{Categories: []string{"oracle-unresolved"}}
723					res.Deliveries = append(res.Deliveries, d)
724					continue
725				}
726				d.Verdict = oq3Score(obs, exp, e)
727				d.Status = map[bool]string{true: "correct", false: "bad"}[d.Verdict.Correct]
728				res.Deliveries = append(res.Deliveries, d)
729			}
730		}
731		return res
732	}
