766	type oq3Summary struct {
767		Mode                  string         `json:"mode"`
768		Source                string         `json:"source"`
769		Trials                int            `json:"controlled_conversation_trials"`
770		ObservedDeliveries    int            `json:"observed_deliveries"`
771		BadObserved           int            `json:"bad_observed_deliveries"`
772		MissingRequired       int            `json:"missing_required_deliveries"`
773		Unexpected            int            `json:"unexpected_requests"`
774		FailureNumber         string         `json:"failure_number"`
775		FailureNumerator      int            `json:"failure_numerator"`
776		CategoryCounts        map[string]int `json:"category_counts_overlapping"`
777		PerFamily             map[string]any `json:"per_family"`
778		PerTrial              map[string]any `json:"per_trial"`
779		OperationVerdicts     map[string]int `json:"operation_verdicts"`
780		RefusalVerdicts       map[string]int `json:"required_refusal_verdicts"`
781		AuxiliaryChecks       map[string]int `json:"auxiliary_checks"`
782		Valid                 bool           `json:"valid"`
783		Invalid               []string       `json:"invalid,omitempty"`
784		ScenariosRun          []string       `json:"scenarios_run"`
785		LedgerSHA256          string         `json:"ledger_sha256"`
786	}
787	
788	func oq3Summarise(results []oq3ScenarioResult, mode, source, ledgerSHA string) oq3Summary {
789		s := oq3Summary{Mode: mode, Source: source, CategoryCounts: map[string]int{}, PerFamily: map[string]any{}, PerTrial: map[string]any{},
790			OperationVerdicts: map[string]int{}, RefusalVerdicts: map[string]int{}, AuxiliaryChecks: map[string]int{}, LedgerSHA256: ledgerSHA, Valid: true}
791		family := map[string]string{}
792		type tally struct{ Observed, Bad, Missing, Correct int }
793		trialT := map[string]*tally{}
794		for _, r := range results {
795			s.ScenariosRun = append(s.ScenariosRun, r.Scenario.ID)
796			for _, tr := range r.Scenario.Trials {
797				family[tr.ID] = tr.Family
798				trialT[tr.ID] = &tally{}
799				s.Trials++
800			}
801			for _, d := range r.Deliveries {
802				t := trialT[d.Trial]
803				switch d.Status {
804				case "correct":
805					s.ObservedDeliveries++
806					t.Observed++
807					t.Correct++
808				case "bad":
809					s.ObservedDeliveries++
810					s.BadObserved++
811					t.Observed++
812					t.Bad++
813				case "missing":
814					s.MissingRequired++
815					t.Missing++
816				case "unexpected":
817					s.ObservedDeliveries++
818					s.Unexpected++
819					s.BadObserved++
820					t.Observed++
821					t.Bad++
822				}
823				for _, c := range d.Verdict.Categories {
824					s.CategoryCounts[c]++
825				}
826			}
827			for _, a := range r.Auxiliary {
828				s.AuxiliaryChecks[a.Status]++
829			}
830			for _, e := range r.Events {
831				switch e.Class {
832				case "operation":
833					s.OperationVerdicts[e.Op+":"+e.Verdict]++
834				case "required-refusal":
835					s.RefusalVerdicts[e.Op+":"+e.Verdict]++
836				}
837			}
838			if len(r.Invalid) > 0 {
839				s.Valid = false
840				s.Invalid = append(s.Invalid, r.Invalid...)
841			}
842		}
843		fam := map[string]*tally{}
844		for id, t := range trialT {
845			f := family[id]
846			if fam[f] == nil {
847				fam[f] = &tally{}
848			}
849			fam[f].Observed += t.Observed
850			fam[f].Bad += t.Bad
851			fam[f].Missing += t.Missing
852			fam[f].Correct += t.Correct
853			s.PerTrial[id] = map[string]any{"family": f, "observed": t.Observed, "correct": t.Correct, "bad": t.Bad, "missing": t.Missing}
854		}
855		famTrials := map[string]int{}
856		for _, f := range family {
857			famTrials[f]++
858		}
859		for f, t := range fam {
860			s.PerFamily[f] = map[string]any{"trials": famTrials[f], "observed": t.Observed, "correct": t.Correct, "bad": t.Bad, "missing": t.Missing,
861				"failure_number": oq3Ratio(t.Bad+t.Missing, famTrials[f])}
862		}
863		s.FailureNumerator = s.BadObserved + s.MissingRequired
864		s.FailureNumber = oq3Ratio(s.FailureNumerator, s.Trials)
865		return s
866	}
867	
868	// oq3Ratio prints an exact fraction and a decimal; a zero denominator is refused, never printed as zero.
869	func oq3Ratio(num, den int) string {
870		if den == 0 {
871			return "undefined (no trials)"
872		}
873		return fmt.Sprintf("%d/%d = %.4f", num, den, float64(num)/float64(den))
874	}
