876	func oq3LedgerSHA(scs []oq3Scenario) (string, []byte) {
877		b, _ := json.MarshalIndent(scs, "", "  ")
878		sum := sha256.Sum256(b)
879		return hex.EncodeToString(sum[:]), b
880	}
