344	// waitFor polls until cond is true or the deadline passes; it never sleeps a fixed interval blindly.
345	func oq3WaitFor(timeout time.Duration, cond func() bool) bool {
346		deadline := time.Now().Add(timeout)
347		for time.Now().Before(deadline) {
348			if cond() {
349				return true
350			}
351			time.Sleep(20 * time.Millisecond)
352		}
353		return cond()
354	}
