356	func (d *oq3Daemon) record(r *http.Request, body []byte, kind string) {
357		d.mu.Lock()
358		defer d.mu.Unlock()
359		d.seq++
360		c := oq3Capture{Seq: d.seq, At: time.Now().Format(time.RFC3339Nano), Method: r.Method, Path: r.URL.Path, Label: d.label, Response: kind}
361		if len(body) > 0 {
362			if json.Valid(body) {
363				c.Body = append(json.RawMessage(nil), body...)
364			} else {
365				c.RawBody = string(body)
366			}
367		}
368		d.captures = append(d.captures, c)
369	}
