435	func (d *oq3Daemon) serveChat(w http.ResponseWriter, r *http.Request, body []byte) {
436		var req struct {
437			Model    string `json:"model"`
438			Messages []struct {
439				Role    string `json:"role"`
440				Content string `json:"content"`
441			} `json:"messages"`
442			Admission json.RawMessage `json:"admission"`
443		}
444		_ = json.Unmarshal(body, &req)
445		d.mu.Lock()
446		label := d.label
447		hold := d.holds[label]
448		failStatus := d.fails[label]
449		promptEval := d.promptEval[label]
450		rounds, done := d.toolRounds[label], d.toolsDone[label]
451		d.mu.Unlock()
452	
453		// The response is chosen from the request's shape and the label's declared behaviour, never
454		// from whether the request carries instructions.
455		kind := "reply"
456		n := len(req.Messages)
457		switch {
458		case n > 0 && req.Messages[0].Role == "system" && strings.HasPrefix(req.Messages[0].Content, oq3CompactionSystemPrefix):
459			kind = "summary"
460		case failStatus != 0:
461			kind = "injected-failure"
462		case n > 0 && req.Messages[n-1].Role == "user" && strings.Contains(req.Messages[n-1].Content, oq3ToolTrigger) && rounds > 0 && done == 0:
463			kind = "toolcall"
464		case n > 0 && req.Messages[n-1].Role == "tool" && done > 0 && done < rounds:
465			kind = "toolcall"
466		}
467		d.record(r, body, kind)
468		if kind == "toolcall" {
469			d.mu.Lock()
470			d.toolsDone[label]++
471			call := d.toolsDone[label]
472			d.mu.Unlock()
473			kind = fmt.Sprintf("toolcall-%d", call)
474		}
475		if hold != nil {
476			select {
477			case <-hold:
478			case <-r.Context().Done():
479				return
480			}
481		}
482		if failStatus != 0 {
483			d.mu.Lock()
484			delete(d.fails, label)
485			d.mu.Unlock()
486			w.Header().Set("Content-Type", "application/json")
487			w.WriteHeader(failStatus)
488			io.WriteString(w, `{"error":"oq3 fake daemon: injected failure"}`)
489			return
490		}
491		model := req.Model
492		if model == "" {
493			model = oq3Model
494		}
495		w.Header().Set("Content-Type", "application/x-ndjson")
496		enc := json.NewEncoder(w)
497		now := "2026-09-26T00:00:00Z"
498		switch {
499		case kind == "summary":
500			enc.Encode(map[string]any{"model": model, "created_at": now, "message": map[string]any{"role": "assistant", "content": "OQ3-SUMMARY: earlier turns were exchanged."}, "done": false})
501		case strings.HasPrefix(kind, "toolcall-"):
502			enc.Encode(map[string]any{"model": model, "created_at": now, "message": map[string]any{"role": "assistant", "content": "", "tool_calls": []any{map[string]any{"id": "call_oq3_" + strings.TrimPrefix(kind, "toolcall-"), "function": map[string]any{"name": "read", "arguments": map[string]any{"path": oq3FixtureFile}}}}}, "done": false})
503		default:
504			enc.Encode(map[string]any{"model": model, "created_at": now, "message": map[string]any{"role": "assistant", "content": d.nextReply()}, "done": false})
505		}
506		final := map[string]any{"model": model, "created_at": now, "message": map[string]any{"role": "assistant", "content": ""}, "done": true, "done_reason": "stop", "prompt_eval_count": 10, "eval_count": 3}
507		if promptEval > 0 {
508			final["prompt_eval_count"] = promptEval
509		}
510		if len(req.Admission) > 0 && string(req.Admission) != "null" {
511			// Blueprint §6.3 A9: the final record of an admitted request carries its diagnostics.
512			final["admission"] = map[string]any{"version": 1, "route": "local", "context_length": 32768, "reserve": 4096, "dropped_messages": 0, "context_exhausted": false}
513		}
514		enc.Encode(final)
515	}
