527		for _, p := range []string{s.home, s.work, s.tmp, s.logs, s.xdg} {
528			if err := os.MkdirAll(p, 0o700); err != nil {
529				t.Fatal(err)
530			}
531		}
532		if err := os.WriteFile(filepath.Join(s.work, oq3FixtureFile), []byte("OQ3 fixture file content.\n"), 0o600); err != nil {
533			t.Fatal(err)
534		}
535		return s
