538	func (s *oq3Sandbox) env(daemonURL string, extra ...string) []string {
539		env := []string{
540			"HOME=" + s.home,
541			"USERPROFILE=" + s.home,
542			"TMPDIR=" + s.tmp,
543			"PATH=" + os.Getenv("PATH"),
544			"TERM=xterm-256color",
545			"LANG=en_AU.UTF-8",
546			"TZ=Australia/Brisbane",
547			"XDG_CONFIG_HOME=" + s.xdg,
548			"OLLAMA_HOST=" + daemonURL,
549			// Network guard: every non-loopback HTTP(S) request goes to a closed local port and fails at
550			// once, so the instrument cannot reach an external service; loopback (the fake daemon) is
551			// never proxied by Go's ProxyFromEnvironment.
552			"HTTP_PROXY=http://127.0.0.1:9",
553			"HTTPS_PROXY=http://127.0.0.1:9",
554			"NO_PROXY=127.0.0.1,localhost",
555		}
556		for _, k := range []string{"USER", "LOGNAME"} {
557			if v := os.Getenv(k); v != "" {
558				env = append(env, k+"="+v)
559			}
560		}
561		return append(env, extra...)
562	}
