572	// oq3HelperCmd prepares a re-executed helper process in the sandbox with a constructed environment.
573	func oq3HelperCmd(s *oq3Sandbox, d *oq3Daemon, mode string, extraEnv ...string) *exec.Cmd {
574		c := exec.Command(os.Args[0], "-test.run=^$")
