597	func oq3StartDesktopWith(fail oq3Fail, s *oq3Sandbox, d *oq3Daemon, life int) *oq3Desktop {
598		token := fmt.Sprintf("oq3-token-%d-%d", time.Now().UnixNano(), life)
599		portFile := filepath.Join(s.tmp, fmt.Sprintf("desktop-%d.port", life))
600		c := oq3HelperCmd(s, d, "desktop", "OQ3_TOKEN="+token, "OQ3_PORT_FILE="+portFile,
601			"OQ3_LOG_FILE="+filepath.Join(s.logs, fmt.Sprintf("desktop-%d.log", life)))
602		var stderr bytes.Buffer
603		c.Stderr = &stderr
604		c.Stdout = &stderr
605		if err := c.Start(); err != nil {
606			fail("start desktop: %v", err)
607		}
608		p := &oq3Desktop{fail: fail, cmd: c, token: token, stderr: &stderr, exited: make(chan error, 1)}
609		go func() { p.exited <- c.Wait() }()
610		var port []byte

597	func oq3StartDesktopWith(fail oq3Fail, s *oq3Sandbox, d *oq3Daemon, life int) *oq3Desktop {
598		token := fmt.Sprintf("oq3-token-%d-%d", time.Now().UnixNano(), life)
599		portFile := filepath.Join(s.tmp, fmt.Sprintf("desktop-%d.port", life))
600		c := oq3HelperCmd(s, d, "desktop", "OQ3_TOKEN="+token, "OQ3_PORT_FILE="+portFile,
601			"OQ3_LOG_FILE="+filepath.Join(s.logs, fmt.Sprintf("desktop-%d.log", life)))
602		var stderr bytes.Buffer
603		c.Stderr = &stderr
604		c.Stdout = &stderr
605		if err := c.Start(); err != nil {
606			fail("start desktop: %v", err)
607		}
608		p := &oq3Desktop{fail: fail, cmd: c, token: token, stderr: &stderr, exited: make(chan error, 1)}
609		go func() { p.exited <- c.Wait() }()
610		var port []byte
611		if !oq3WaitFor(20*time.Second, func() bool {
612			b, err := os.ReadFile(portFile)
613			if err == nil && len(b) > 0 {
614				port = b
615				return true
616			}
617			return false
618		}) {
619			_ = c.Process.Kill()
620			fail("desktop process %d never published its port; stderr=%s", life, stderr.String())
621		}
622		p.base = "http://127.0.0.1:" + string(port)
623		return p
624	}
