626	// stop ends the desktop process the way the operator quitting does (SIGTERM) and waits for it, so
627	// that a later lifetime can only have read what the earlier one persisted.
628	func (p *oq3Desktop) stop() {
629		if err := p.stopNoFatal(); err != nil {
630			p.fail("%v", err)
631		}
632	}
633	
634	func (p *oq3Desktop) stopNoFatal() error {
635		_ = p.cmd.Process.Signal(syscall.SIGTERM)
636		select {
637		case err := <-p.exited:
638			if err != nil {
639				return fmt.Errorf("desktop process exit: %v; output=%s", err, p.stderr.String())
640			}
641			return nil
642		case <-time.After(15 * time.Second):
643			_ = p.cmd.Process.Kill()
644			return fmt.Errorf("desktop process did not exit on SIGTERM")
645		}
646	}
