659	// doAuth never fails the test: a transport error is returned in the result (status -1), so it is
660	// safe from any goroutine; callers decide whether it is a harness failure.
661	func (p *oq3Desktop) doAuth(method, path string, body any, auth bool) oq3HTTPResult {
662		var rd io.Reader
663		if body != nil {
664			b, err := json.Marshal(body)
665			if err != nil {
666				return oq3HTTPResult{Status: -1, Error: err.Error()}
667			}
668			rd = bytes.NewReader(b)
669		}
670		req, err := http.NewRequest(method, p.base+path, rd)
671		if err != nil {
672			return oq3HTTPResult{Status: -1, Error: err.Error()}
673		}
674		req.Header.Set("Content-Type", "application/json")
675		if auth {
676			req.AddCookie(&http.Cookie{Name: "token", Value: p.token})
677		}
678		resp, err := (&http.Client{Timeout: 90 * time.Second}).Do(req)
679		if err != nil {
680			return oq3HTTPResult{Status: -1, Error: err.Error()}
681		}
682		defer resp.Body.Close()
683		data, _ := io.ReadAll(resp.Body)
684		return oq3HTTPResult{Status: resp.StatusCode, ContentType: resp.Header.Get("Content-Type"), Body: string(data)}
685	}
