692	// chatBody sends one turn and returns the chat id the stream reports.
693	func (p *oq3Desktop) chatBody(id string, body map[string]any) (string, oq3HTTPResult) {
694		res := p.do(http.MethodPost, "/api/v1/chat/"+id, body)
695		chatID := id
696		sc := bufio.NewScanner(strings.NewReader(res.Body))
697		sc.Buffer(make([]byte, 1<<20), 1<<20)
698		for sc.Scan() {
699			var ev struct {
700				EventName string  `json:"eventName"`
701				ChatID    *string `json:"chatId"`
702			}
703			if json.Unmarshal(sc.Bytes(), &ev) == nil && ev.ChatID != nil && *ev.ChatID != "" {
704				chatID = *ev.ChatID
705			}
706		}
707		return chatID, res
708	}
