737	// oq3StartTerminalWith starts either the launch-function helper (argv nil) or a given program
738	// (the built binary for the entry arm) on a fresh pseudo-terminal.
739	func oq3StartTerminalWith(fail oq3Fail, s *oq3Sandbox, d *oq3Daemon, session, model string, argv []string) *oq3Terminal {
740		master, slave, err := oq3OpenPTY()
741		if err != nil {
742			fail("pty: %v", err)
743		}
744		var c *exec.Cmd
745		if argv == nil {
746			c = oq3HelperCmd(s, d, "terminal", "OQ3_MODEL="+model)
747		} else {
748			c = exec.Command(argv[0], argv[1:]...)
749			c.Dir = s.work
750			c.Env = s.env(d.srv.URL)
751		}
752		c.Stdin, c.Stdout, c.Stderr = slave, slave, slave
753		c.SysProcAttr = &syscall.SysProcAttr{Setsid: true, Setctty: true, Ctty: 0}
754		if err := c.Start(); err != nil {
755			fail("start terminal: %v", err)
756		}
757		slave.Close()
758		p := &oq3Terminal{fail: fail, cmd: c, master: master, exited: make(chan error, 1)}
759		go p.readLoop(filepath.Join(s.logs, "terminal-"+session+".raw"))
760		go func() {
761			err := c.Wait()
762			p.mu.Lock()
763			p.gone = true
764			p.mu.Unlock()
765			p.exited <- err
766		}()
767		return p
768	}
