807	// readLoop keeps the transcript and answers the terminal queries a real emulator would answer
808	// (background colour, foreground colour, cursor position, device attributes).
809	func (p *oq3Terminal) readLoop(rawPath string) {
810		f, _ := os.Create(rawPath)
811		defer func() {
812			if f != nil {
813				f.Close()
814			}
815		}()
816		buf := make([]byte, 64*1024)
817		for {
818			n, err := p.master.Read(buf)
819			if n > 0 {
820				chunk := buf[:n]
821				if f != nil {
822					f.Write(chunk)
823				}
824				p.mu.Lock()
825				p.raw.Write(chunk)
826				p.mu.Unlock()
827				s := string(chunk)
828				if strings.Contains(s, "\x1b]11;?") {
829					p.master.Write([]byte("\x1b]11;rgb:1c1c/1c1c/1c1c\x1b\\"))
830				}
831				if strings.Contains(s, "\x1b]10;?") {
832					p.master.Write([]byte("\x1b]10;rgb:e0e0/e0e0/e0e0\x1b\\"))
833				}
834				if strings.Contains(s, "\x1b[6n") {
835					p.master.Write([]byte("\x1b[1;1R"))
836				}
837				if strings.Contains(s, "\x1b[c") || strings.Contains(s, "\x1b[0c") {
838					p.master.Write([]byte("\x1b[?62;22c"))
839				}
840			}
841			if err != nil {
842				return
843			}
844		}
845	}
