859	// quiet waits until the program has produced no output for the given interval.
860	func (p *oq3Terminal) quiet(interval, timeout time.Duration) bool {
861		deadline := time.Now().Add(timeout)
862		last := p.rawLen()
863		lastChange := time.Now()
864		for time.Now().Before(deadline) {
865			time.Sleep(25 * time.Millisecond)
866			if n := p.rawLen(); n != last {
867				last, lastChange = n, time.Now()
868				continue
869			}
870			if time.Since(lastChange) >= interval {
871				return true
872			}
873		}
874		return false
875	}
876	
877	func (p *oq3Terminal) screenContainsAfter(mark int, text string) bool {
878		p.mu.Lock()
879		raw := p.raw.String()
880		p.mu.Unlock()
881		if mark > len(raw) {
882			mark = len(raw)
883		}
884		return strings.Contains(oq3ANSI.ReplaceAllString(raw[mark:], ""), text)
885	}
