939	// oq3RunCLIWith runs one CLI invocation: the root command in a re-executed helper process, or the
940	// built binary when one is given (the entry arm).
941	func oq3RunCLIWith(fail oq3Fail, s *oq3Sandbox, d *oq3Daemon, binary []string, args ...string) oq3CLIResult {
942		var c *exec.Cmd
943		if binary == nil {
944			a, _ := json.Marshal(args)
945			c = oq3HelperCmd(s, d, "cli", "OQ3_ARGS="+string(a))
946		} else {
947			c = exec.Command(binary[0], append(append([]string{}, binary[1:]...), args...)...)
948			c.Dir = s.work
949			c.Env = s.env(d.srv.URL)
950		}
951		out, err := c.CombinedOutput()
952		code := 0
953		if err != nil {
954			var ee *exec.ExitError
955			if !errors.As(err, &ee) {
956				fail("cli %v: %v", args, err)
957			}
958			code = ee.ExitCode()
959		}
960		return oq3CLIResult{Args: args, ExitCode: code, Output: string(out)}
961	}

