 20	func oq3MustNorm(t *testing.T, s string) any {
 21		t.Helper()
 22		v, err := oq3Normalise([]byte(s), "")
 23		if err != nil {
 24			t.Fatalf("fixture does not parse: %v\n%s", err, s)
 25		}
 26		return v
 27	}
