 34	func TestOQ3ScorerControls(t *testing.T) {
 35		A, B := oq3Texts["A"], oq3Texts["B"]
 36		ms1 := oq3ModelSystem
 37		// Header text written out literally from blueprint §5, independently of oq3Header.
 38		hA11 := "User-configured instructions; revision 1; selection 1:\n"
 39		hB23 := "User-configured instructions; revision 2; selection 3:\n"
 40	
 41		desktopGolden := `{"model":"oq3-model","messages":[{"role":"user","content":"Hello."}],"stream":true,"options":null}`
 42		desktopExpected := `{"model":"oq3-model","messages":[{"role":"system","content":` + oq3JSONString(ms1+"\n\n"+hA11+A) + `},{"role":"user","content":"Hello."}],"stream":true,"options":null,"admission":{"version":1}}`
 43		terminalGolden := `{"model":"oq3-model","messages":[{"role":"system","content":"BASE PROMPT"},{"role":"user","content":"Hi."}],"options":{}}`
 44		terminalExpected := `{"model":"oq3-model","messages":[{"role":"system","content":` + oq3JSONString("BASE PROMPT\n\n"+hB23+B) + `},{"role":"user","content":"Hi."}],"options":{},"admission":{"version":1}}`
 45		terminalOffGolden := `{"model":"oq3-model","messages":[{"role":"user","content":"Hi."}],"options":{}}`
 46		terminalOffExpected := `{"model":"oq3-model","messages":[{"role":"system","content":` + oq3JSONString(hA11+A) + `},{"role":"user","content":"Hi."}],"options":{},"admission":{"version":1}}`
 47	
 48		ms := func(model string) (string, bool) {
 49			if model == "oq3-model" {
 50				return ms1, true
 51			}
 52			return "", false
 53		}
 54		eD := cD(1, 1, "A")
 55		eT := cT(2, 3, "B")
 56		eTOff := cT(1, 1, "A")
 57	
 58		// 1. The transform matches the hand-written expectation in all three shapes.
 59		for _, c := range []struct {
 60			name, golden, expected string
 61			e                      oq3Expect
 62		}{{"desktop", desktopGolden, desktopExpected, eD}, {"terminal", terminalGolden, terminalExpected, eT}, {"terminal-system-off", terminalOffGolden, terminalOffExpected, eTOff}} {
 63			got, err := oq3Transform(oq3MustNorm(t, c.golden), c.e, ms)
 64			if err != nil {
 65				t.Fatalf("%s transform: %v", c.name, err)
 66			}
 67			if !reflect.DeepEqual(got, oq3MustNorm(t, c.expected)) {
 68				gb, _ := json.Marshal(got)
 69				t.Fatalf("%s transform differs from the hand-written expectation:\n got %s\nwant %s", c.name, gb, c.expected)
 70			}
 71			// 2. A perfect delivery scores correct.
 72			if v := oq3Score(oq3MustNorm(t, c.expected), got, c.e); !v.Correct {
 73				t.Fatalf("%s: a perfect delivery scored %+v", c.name, v)
 74			}
 75		}
 76		// A desktop golden that already leads with a system message (MCP) must not be guessed.
 77		if _, err := oq3Transform(oq3MustNorm(t, `{"model":"oq3-model","messages":[{"role":"system","content":"MCP"},{"role":"user","content":"x"}]}`), eD, ms); err == nil {
 78			t.Fatal("the oracle guessed the unspecified model-system/MCP join")
 79		}
 80	
 81		exp := oq3MustNorm(t, desktopExpected)
 82		sys := func(content string) string { return `{"role":"system","content":` + oq3JSONString(content) + `}` }
 83		user := `{"role":"user","content":"Hello."}`
 84		adm := `,"admission":{"version":1}`
 85		tail := `,"stream":true,"options":null`
 86		cases := []struct {
 87			name     string
 88			observed string
 89			e        oq3Expect
 90			expected any
 91			want     []string // every one must be present
 92		}{
 93			{"missing carrier", desktopGolden, eD, exp, []string{"missing", "admission-missing"}},
 94			{"wrong revision", `{"model":"oq3-model","messages":[` + sys(ms1+"\n\nUser-configured instructions; revision 2; selection 1:\n"+A) + `,` + user + `]` + tail + adm + `}`, eD, exp, []string{"wrong-revision"}},
 95			{"wrong generation", `{"model":"oq3-model","messages":[` + sys(ms1+"\n\nUser-configured instructions; revision 1; selection 2:\n"+A) + `,` + user + `]` + tail + adm + `}`, eD, exp, []string{"wrong-revision"}},
 96			{"duplicated", `{"model":"oq3-model","messages":[` + sys(ms1+"\n\n"+hA11+A) + `,` + sys(hA11+A) + `,` + user + `]` + tail + adm + `}`, eD, exp, []string{"duplicated"}},
 97			{"altered text", `{"model":"oq3-model","messages":[` + sys(ms1+"\n\n"+hA11+strings.Replace(A, "SENTINEL-A-MID-9e41 ", "", 1)) + `,` + user + `]` + tail + adm + `}`, eD, exp, []string{"altered"}},
 98			{"base lost", `{"model":"oq3-model","messages":[` + sys(hA11+A) + `,` + user + `]` + tail + adm + `}`, eD, exp, []string{"base-lost"}},
 99			{"misplaced in the user message", `{"model":"oq3-model","messages":[{"role":"user","content":` + oq3JSONString("Hello.\n\n"+hA11+A) + `}]` + tail + adm + `}`, eD, exp, []string{"misplaced"}},
100			{"admission missing only", `{"model":"oq3-model","messages":[` + sys(ms1+"\n\n"+hA11+A) + `,` + user + `]` + tail + `}`, eD, exp, []string{"admission-missing"}},
101			{"history changed", `{"model":"oq3-model","messages":[` + sys(ms1+"\n\n"+hA11+A) + `,{"role":"user","content":"Hello!"}]` + tail + adm + `}`, eD, exp, []string{"request-changed"}},
102			{"unexpected carrier", `{"model":"oq3-model","messages":[` + sys(ms1+"\n\n"+hA11+A) + `,` + user + `]` + tail + adm + `}`, nD(), oq3MustNorm(t, desktopGolden), []string{"unexpected-carrier", "unexpected-admission", "leaked"}},
103			{"multi-defect", `{"model":"oq3-model","messages":[` + sys("User-configured instructions; revision 3; selection 1:\n"+A) + `,` + user + `]` + tail + `}`, eD, exp, []string{"wrong-revision", "base-lost", "admission-missing"}},
104			{"extra field on the carrier message", `{"model":"oq3-model","messages":[{"role":"system","content":` + oq3JSONString(ms1+"\n\n"+hA11+A) + `,"images":[]},` + user + `]` + tail + adm + `}`, eD, exp, []string{"other"}},
105		}
106		for _, c := range cases {
107			v := oq3Score(oq3MustNorm(t, c.observed), c.expected, c.e)
108			if v.Correct {
109				t.Fatalf("%s: a faulty delivery scored correct", c.name)
110			}
111			for _, w := range c.want {
112				found := false
113				for _, got := range v.Categories {
114					if got == w {
115						found = true
116					}
117				}
118				if !found {
119					t.Fatalf("%s: category %q not reported; got %v (%s)", c.name, w, v.Categories, v.Detail)
120				}
121			}
122			t.Logf("control %-36s -> %v", c.name, v.Categories)
123		}
124	
125		// 3. Summariser expectations.
126		clean := `{"model":"oq3-model","messages":[{"role":"system","content":"Summarize the archived part of an Ollama agent conversation. Keep goals."},{"role":"user","content":"archive"}]}`
127		if v := oq3CheckSummariser(oq3MustNorm(t, clean)); !v.Correct {
128			t.Fatalf("clean summariser scored %+v", v)
129		}
130		for name, s := range map[string]string{
131			"summariser-carries-header":  `{"messages":[{"role":"system","content":"Summarize the archived part of an Ollama agent conversation."},{"role":"user","content":` + oq3JSONString("archive "+hA11) + `}]}`,
132			"summariser-carries-profile": `{"messages":[{"role":"system","content":"Summarize the archived part of an Ollama agent conversation."},{"role":"user","content":"archive SENTINEL-B-END-83d9"}]}`,
133			"summariser-prompt-replaced": `{"messages":[{"role":"system","content":"something else"},{"role":"user","content":"archive"}]}`,
134		} {
135			v := oq3CheckSummariser(oq3MustNorm(t, s))
136			if v.Correct || !strings.Contains(strings.Join(v.Categories, ","), name) {
137				t.Fatalf("summariser control %s: %+v", name, v)
138			}
139		}
140	
141		// 4. Arithmetic: counts reconcile, a multi-defect request counts once, and the ratio is exact.
142		sc := oq3Scenario{ID: "SYN", Trials: []oq3Trial{{"S-a", famSave, "desktop", ""}, {"S-b", famEdit, "desktop", ""}, {"S-c", famDisable, "terminal", ""}}}
143		res := oq3ScenarioResult{Scenario: sc, Deliveries: []oq3Delivery{
144			{Trial: "S-a", Status: "correct", Verdict: oq3DeliveryVerdict{Correct: true}},
145			{Trial: "S-a", Status: "bad", Verdict: oq3DeliveryVerdict{Categories: []string{"missing", "admission-missing"}}},
146			{Trial: "S-b", Status: "missing", Verdict: oq3DeliveryVerdict{Categories: []string{"not-dispatched"}}},
147			{Trial: "S-c", Status: "unexpected", Verdict: oq3DeliveryVerdict{Categories: []string{"unexpected-request"}}},
148			{Trial: "S-c", Status: "bad", Verdict: oq3DeliveryVerdict{Categories: []string{"wrong-revision", "base-lost", "admission-missing"}}},
149		}}
150		s := oq3Summarise([]oq3ScenarioResult{res}, "control", "synthetic", "none")
151		if s.Trials != 3 || s.ObservedDeliveries != 4 || s.BadObserved != 3 || s.MissingRequired != 1 || s.Unexpected != 1 || s.FailureNumerator != 4 || s.FailureNumber != "4/3 = 1.3333" {
152			t.Fatalf("arithmetic control: %+v", s)
153		}
154		if s.CategoryCounts["admission-missing"] != 2 || s.CategoryCounts["not-dispatched"] != 1 {
155			t.Fatalf("category control: %v", s.CategoryCounts)
156		}
157		if oq3Ratio(0, 0) == "0/0 = 0.0000" {
158			t.Fatal("a zero denominator printed as a number")
159		}
