162	func TestOQ3RunnerControls(t *testing.T) {
163		all := oq3AllScenarios()
164		// Empty and unknown selections are refused.
165		if _, err := oq3Select(all, ""); err == nil {
166			t.Fatal("empty selection accepted")
167		}
168		if _, err := oq3Select(all, "D1,NOPE"); err == nil {
169			t.Fatal("unknown scenario accepted")
170		}
171		// Frozen trial identities are unique across the ledger.
172		seen := map[string]bool{}
173		ids := []string{}
174		for _, sc := range all {
175			for _, tr := range sc.Trials {
176				if seen[tr.ID] {
177					t.Fatalf("duplicate trial %s", tr.ID)
178				}
179				seen[tr.ID] = true
180				ids = append(ids, tr.ID)
181			}
182			for i, st := range sc.Steps {
183				if st.Class == "required-dispatch" && (st.Trial == "" || !seen[st.Trial] && !oq3TrialIn(sc, st.Trial)) {
184					t.Fatalf("%s step %d dispatches for an undeclared trial %q", sc.ID, i, st.Trial)
185				}
186			}
187		}
188		sort.Strings(ids)
189		t.Logf("ledger: %d scenarios, %d trials", len(all), len(ids))
190	
191		// A missing trial is caught by the completeness check.
192		sel, _ := oq3Select(all, "D1")
193		if p := oq3Completeness(sel, []oq3ScenarioResult{{Scenario: sel[0]}}); len(p) == 0 {
194			t.Fatal("a trial with no delivery record passed completeness")
195		}
196		if p := oq3Completeness(sel, nil); len(p) == 0 {
197			t.Fatal("a scenario with no result passed completeness")
198		}
199	
200		goldens := t.TempDir()
201		// Harness faults on a real desktop scenario: each must make the run invalid, not change the number.
202		for _, fault := range []string{"malformed-capture", "extra-request", "unknown-label", "none"} {
203			d := oq3StartDaemon(t)
204			s := oq3NewSandbox(t, "RC-"+fault)
205			sc := oq3Scenario{ID: "RC", Trials: []oq3Trial{{"RC-X", famSave, "desktop", ""}},
206				Steps: []oq3Step{h("desktop-start"), dTurn("RC-X", "X", "OQ3 runner control turn.", nD()), h("desktop-stop")}}
207			run := oq3NewRun(t, sc, d, s)
208			run.execute()
209			label := oq3Label("RC", 1, "desktop-turn")
210			switch fault {
211			case "malformed-capture":
212				d.setLabel(label)
213				oq3PostRaw(t, d, []byte(`{"model":"oq3-model","messages":[`))
214			case "extra-request":
215				d.setLabel(label)
216				oq3PostRaw(t, d, []byte(`{"model":"oq3-model","messages":[{"role":"user","content":"extra"}]}`))
217			case "unknown-label":
218				d.setLabel("RC/99/nowhere")
219				oq3PostRaw(t, d, []byte(`{"model":"oq3-model","messages":[{"role":"user","content":"stray"}]}`))
220			}
221			res := run.score(goldens, true, "runner control")
222			if fault == "none" {
223				if len(res.Invalid) != 0 {
224					t.Fatalf("clean control run invalid: %v", res.Invalid)
225				}
226				continue
227			}
228			if len(res.Invalid) == 0 {
229				t.Fatalf("harness fault %s did not make the run invalid", fault)
230			}
231			t.Logf("harness fault %-18s -> invalid: %v", fault, res.Invalid)
232		}
233	
234		// A failing child: a terminal session for a model the daemon does not have exits at once; the
235		// step is a harness failure and the run is invalid, never a missing delivery.
236		d := oq3StartDaemon(t)
237		s := oq3NewSandbox(t, "RC-child")
238		sc := oq3Scenario{ID: "RCC", Trials: []oq3Trial{{"RCC-X", famSave, "terminal", ""}},
239			Steps: []oq3Step{with(h("terminal-start"), "model", "no-such-model"), tTurn("RCC-X", "OQ3 turn that must not be scored.", nT()), h("terminal-stop")}}
240		run := oq3NewRun(t, sc, d, s)
241		run.execute()
242		res := run.score(goldens, true, "runner control")
243		if len(res.Invalid) == 0 {
244			t.Fatal("a failing child process did not make the run invalid")
245		}
246		t.Logf("failing child -> invalid: %v", res.Invalid)
247	}
