 145	func (m *chatModel) submitInput(input string) (tea.Model, tea.Cmd) {
 146		command, args, _ := slashCommandInvocation(input)
 147		if command != "" {
 148			input = strings.TrimSpace(command + " " + args)
 149		}
 150		skillName, skillPrompt, skillOK := m.skillSlashInvocation(input)
 151	
 152		switch {
 153		case command == "/bye":
 154			m.quitting = true
 155			return *m, m.quitCmd()
 156		case command == "/help":
 157			m.entries = append(m.entries, newSlashEntry(m.helpSummary()))
 158			return *m, nil
 159		case command == "/model":
 160			return m.openModelPicker(args)
 161		case command == "/think" && args == "":
 162			return m.openThinkPicker()
 163		case command == "/think":
 164			return m.handleThinkCommand(args)
 165		case command == "/tools":
 166			return m.handleToolsCommand(args)
 167		case command == "/system":
 168			return m.handleSystemCommand(args)
 169		case command == "/skills":
 170			return m.handleSkillsCommand(args)
 171		case command == "/mcp":
 172			return m.handleMCPCommand(args)
 173		case command == "/prompt":
 174			return m.handlePromptCommand(args)
 175		case command == "/save":
 176			return m.handleSaveCommand(args)
 177		case command == "/new" && args == "":
 178			return m.resetChat("new chat")
 179		case command == "/compact" && args == "":
 180			return m.startManualCompaction()
 181		case skillOK:
 182			return m.startSkillRun(skillName, skillPrompt)
 183		case strings.HasPrefix(input, "/") && m.slashInputIsMultimodalFile(input):
 184			return m.startRun(input)
 185		case strings.HasPrefix(input, "/"):
 186			m.entries = append(m.entries, newChatEntry(chatEntry{role: "error", content: fmt.Sprintf("Unknown command %q", strings.Fields(input)[0])}))
 187			return *m, nil
 188		}
 189	
 190		return m.startRun(input)
 191	}
