 193	func (m *chatModel) handleSkillsCommand(args string) (tea.Model, tea.Cmd) {
 194		if fields := strings.Fields(args); len(fields) == 2 && fields[0] == "import" {
 195			return m.handleSkillsImport(fields[1])
 196		} else if len(fields) != 0 {
 197			m.entries = append(m.entries, newChatEntry(chatEntry{role: "error", content: "usage: /skills [import codex|claude|pi]"}))
 198			return *m, nil
 199		}
 200		skills := m.opts.Skills.List()
 201		if len(skills) == 0 {
 202			m.entries = append(m.entries, newSlashEntry("No skills found. Add directories containing SKILL.md under "+skillsDirForDisplay(m.opts.Skills)+"."))
 203			return *m, nil
 204		}
 205		lines := []string{"Available skills:"}
 206		for _, skill := range skills {
 207			description := skill.Description
 208			if description == "" {
 209				description = "No description provided."
 210			}
 211			lines = append(lines, fmt.Sprintf("- `%s`: %s", skill.Name, description))
 212		}
 213		lines = append(lines, "\nType `/<name>` to load a skill into the conversation.")
 214		m.entries = append(m.entries, newSlashEntry(strings.Join(lines, "\n")))
 215		return *m, nil
 216	}
