 218	// handleMCPCommand lists MCP servers and switches them on or off.
 219	//
 220	// It deliberately cannot approve one. Approving a server means agreeing to run
 221	// a particular command line, which has to be shown verbatim and answered
 222	// deliberately; a chat input line is the wrong place for that, so approval
 223	// stays with `ollama mcp approve`.
 224	func (m *chatModel) handleMCPCommand(args string) (tea.Model, tea.Cmd) {
 225		fields := strings.Fields(args)
 226		switch {
 227		case len(fields) == 0:
 228			return m.showMCPServers()
 229		case len(fields) == 2 && (fields[0] == "enable" || fields[0] == "disable"):
 230			return m.setMCPEnabled(fields[1], fields[0] == "enable")
 231		default:
 232			m.status = "error"
 233			m.entries = append(m.entries, newChatEntry(chatEntry{role: "error", content: "usage: /mcp [enable|disable <name>]"}))
 234			return *m, nil
 235		}
