 351	func skillsImportSummary(result coreagent.SkillImportResult) string {
 352		if len(result.Imported) == 0 && len(result.Existing) == 0 && len(result.Failures) == 0 {
 353			return fmt.Sprintf("No %s skills found at %s.", result.Source, result.SourceDir)
 354		}
 355		var lines []string
 356		if len(result.Imported) != 0 {
 357			lines = append(lines, fmt.Sprintf("Imported %d skill%s from %s.", len(result.Imported), pluralSuffix(len(result.Imported)), result.SourceDir))
 358		}
 359		if len(result.Existing) != 0 {
 360			lines = append(lines, "Already present (left unchanged): "+strings.Join(result.Existing, ", ")+".")
 361		}
 362		for _, failure := range result.Failures {
 363			lines = append(lines, fmt.Sprintf("Skipped %s: %v.", failure.Name, failure.Err))
 364		}
 365		return strings.Join(lines, "\n")
 366	}
